/*
 * TimerOverlay: a countdown started over MQTT (timer/set), drawn as variant A
 * (stacked minutes / seconds, 3x5 digits) or B (big 4x7 digits + seconds
 * ring), red in the last 10 s, blinking when it has run out.
 *
 * The reference pictures below are copied from the design notes
 * (wortuhr/08-symbole-und-timer.md), not generated by the code under test.
 * '.' off, '-' dimmed ring, w/o/r the timer colours.
 */

#include "TimerOverlay.h"

#include "support/check.h"

#include <string>

namespace {

char codeOf(const RgbColor &c) {
    if (c == timer::OFF)
        return '.';
    if (c == timer::DIM)
        return '-';
    if (c == timer::MINUTES)
        return 'w';
    if (c == timer::SECONDS)
        return 'o';
    if (c == timer::ALERT)
        return 'r';
    return '?';
}

std::string picture(const RgbColor *frame) {
    std::string s;
    for (int row = 0; row < 10; row++) {
        for (int col = 0; col < 11; col++) {
            s += codeOf(frame[row * 11 + col]);
        }
        s += '\n';
    }
    return s;
}

void expectPicture(const RgbColor *frame, const char *const expected[10],
                   const char *what) {
    std::string want;
    for (int row = 0; row < 10; row++) {
        for (const char *p = expected[row]; *p; p++) {
            if (*p != ' ') {
                want += *p;
            }
        }
        want += '\n';
    }
    const std::string got = picture(frame);
    if (got != want) {
        printf("--- %s\nwant:\n%sgot:\n%s", what, want.c_str(), got.c_str());
    }
    check(got == want, what);
}

const char *const A_12_34[10] = {
    ". . . w . . w w w . .", ". . w w . . . . w . .", ". . . w . . w w w . .",
    ". . . w . . w . . . .", ". . w w w . w w w . .", ". . o o o . o . o . .",
    ". . . . o . o . o . .", ". . o o o . o o o . .", ". . . . o . . . o . .",
    ". . o o o . . . o . .",
};

const char *const B_12_34[10] = {
    "- - - - - o o o o o o", "- . . w . . . w w . o", "- . w w . . w . . w o",
    "- . . w . . . . . w o", "- . . w . . . . w . o", "- . . w . . . w . . o",
    "- . . w . . w . . . o", "- . w w w . w w w w o", "- . . . . . . . . . o",
    "- - - o o o o o o o o",
};

const char *const B_0_42[10] = {
    "- - - - - o o o o o o", "- o . . o . . o o . o", "- o . . o . o . . o o",
    "- o . . o . . . . o o", "- o o o o . . . o . o", "- . . . o . . o . . o",
    "- . . . o . o . . . o", "o . . . o . o o o o o", "o . . . . . . . . . o",
    "o o o o o o o o o o o",
};

void referencePictures() {
    RgbColor frame[timer::PIXELS];
    timer::render(12 * 60 + 34, timer::Variant::A, false, frame);
    expectPicture(frame, A_12_34, "variant A, 12:34 matches the design");
    timer::render(12 * 60 + 34, timer::Variant::B, false, frame);
    expectPicture(frame, B_12_34, "variant B, 12:34 matches the design");
    timer::render(42, timer::Variant::B, false, frame);
    expectPicture(frame, B_0_42,
                  "variant B, 0:42: last minute shows big seconds");
}

void lastTenSecondsAreRed() {
    RgbColor frame[timer::PIXELS];
    timer::render(9, timer::Variant::B, false, frame);
    const std::string p = picture(frame);
    check(p.find('o') == std::string::npos && p.find('w') == std::string::npos,
          "B at 0:09: nothing orange or white left");
    check(p.find('r') != std::string::npos, "B at 0:09: lit pixels are red");
    check(codeOf(frame[0]) == '-', "B at 0:09: the unlit ring stays dimmed");

    timer::render(10, timer::Variant::A, false, frame);
    check(picture(frame).find('r') == std::string::npos,
          "A at 0:10: not red yet");
    timer::render(9, timer::Variant::A, false, frame);
    check(picture(frame).find('w') == std::string::npos &&
              picture(frame).find('r') != std::string::npos,
          "A at 0:09: red");
}

void alarmBlinks() {
    RgbColor on[timer::PIXELS], off[timer::PIXELS];
    timer::render(0, timer::Variant::A, true, on);
    timer::render(0, timer::Variant::A, false, off);
    check(picture(on).find('r') != std::string::npos, "alarm phase on: red");
    check(picture(off).find('r') == std::string::npos &&
              picture(off).find('w') == std::string::npos,
          "alarm phase off: dark");
}

void cornersStayOff() {
    RgbColor frame[timer::PIXELS];
    timer::render(12 * 60 + 34, timer::Variant::B, false, frame);
    bool off = true;
    for (int i = 110; i < timer::PIXELS; i++) {
        off &= frame[i] == timer::OFF;
    }
    check(off, "the four minute LEDs stay off");
}

void countdown() {
    TimerOverlay t;
    check(t.state() == timer::State::Idle, "idle at start");
    check(t.start(300, timer::Variant::A, 30, 1000) == timer::Error::None,
          "start 5:00");
    check(t.state() == timer::State::Running, "running");
    check(t.remaining(1000) == 300, "5:00 at the start");
    check(t.remaining(1999) == 300, "still 5:00 999 ms later (rounds up)");
    check(t.remaining(2000) == 299, "4:59 after one second");
    check(t.remaining(300999) == 1, "0:01 in the last second");

    RgbColor frame[timer::PIXELS];
    bool changed = false;
    check(t.update(301000, frame, changed) == timer::State::Alarm,
          "0:00: alarm");
    check(t.update(331000, frame, changed) == timer::State::Idle,
          "after 30 s of alarm it is over");
}

void updateReportsChangesOncePerSecond() {
    TimerOverlay t;
    t.start(60, timer::Variant::B, 30, 0);
    RgbColor frame[timer::PIXELS];
    bool changed = false;
    t.update(0, frame, changed);
    check(changed, "first update draws");
    t.update(500, frame, changed);
    check(!changed, "same second: nothing to redraw");
    t.update(1000, frame, changed);
    check(changed, "next second: redraw");
}

void addAndLimits() {
    TimerOverlay t;
    check(t.add(120, 0) == timer::Error::None && t.remaining(0) == 120,
          "add on an idle timer starts it");
    check(t.add(60, 0) == timer::Error::None && t.remaining(0) == 180,
          "add extends a running timer");
    check(t.add(-170, 0) == timer::Error::None && t.remaining(0) == 10,
          "a negative add shortens it");
    check(t.add(-600, 0) == timer::Error::None && t.remaining(0) == 0,
          "it cannot go below zero");
    check(t.start(0, timer::Variant::A, 30, 0) == timer::Error::BadDuration,
          "zero seconds is rejected");
    check(t.start(100 * 60, timer::Variant::A, 30, 0) ==
              timer::Error::BadDuration,
          "100 minutes exceeds two digits");
    check(t.start(99 * 60 + 59, timer::Variant::A, 30, 0) == timer::Error::None,
          "99:59 is the maximum");
    t.stop();
    check(t.state() == timer::State::Idle, "stop() ends it");
}

void millisWrapAround() {
    TimerOverlay t;
    const uint32_t start = 0xFFFFF000U;
    uint32_t later = start;
    later += 4096; // wraps past zero like millis() does
    t.start(10, timer::Variant::A, 5, start);
    check(t.remaining(later) == 6,
          "remaining time is right across the millis() wrap");
}

} // namespace

int main() {
    referencePictures();
    lastTenSecondsAreRed();
    alarmBlinks();
    cornersStayOff();
    countdown();
    updateReportsChangesOncePerSecond();
    addAndLimits();
    millisWrapAround();

    return report("timer overlay");
}
